import os
import re
import subprocess
import psutil
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/monitor/commands', methods=['POST'])
def monitor_commands():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"code": 400, "message": "Invalid JSON body"}), 400

    command_regex = data.get('command_regex')
    filter_flags = data.get('filter_flags', '')

    if not isinstance(command_regex, str):
        return jsonify({"code": 400, "message": "'command_regex' must be a string"}), 400

    # Build ps command
    # ps aux shows all processes; we filter by regex on the command column
    # The command column is the 11th field in ps aux output (0-indexed after USER, PID, %CPU, %MEM, VSZ, RSS, TTY, STAT, START, TIME, CMD)
    # Using grep -E with the regex to match the command field.
    # We need to anchor the regex to avoid matching the header line.
    # ps aux output format: USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND
    # The COMMAND field may contain spaces, so we use a trick: output full command line and filter by regex.
    # Simpler: use ps -eo pid,comm --no-headers and then grep -E.
    cmd = ['ps', '-eo', 'pid,comm', '--no-headers']
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
    except Exception as e:
        return jsonify({"code": 500, "message": f"Failed to run ps: {e}"}), 500

    lines = proc.stdout.strip().splitlines()
    matches = []
    pattern = re.compile(command_regex, re.IGNORECASE)
    for line in lines:
        parts = line.strip().split(None, 1)
        if len(parts) < 2:
            continue
        pid_str, comm = parts[0], parts[1]
        if pattern.search(comm):
            try:
                pid = int(pid_str)
                matches.append({"processId": pid, "processString": comm})
            except ValueError:
                continue

    # Optional sorting based on filter_flags (e.g., "-rss" to sort by memory)
    # For simplicity, we just return the list as-is.
    return jsonify({"processes": matches}), 200


@app.errorhandler(405)
def method_not_allowed(e):
    return jsonify({"code": 405, "message": "Method not allowed"}), 405


@app.errorhandler(415)
def unsupported_media_type(e):
    return jsonify({"code": 415, "message": "Unsupported media type"}), 415


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

